CREATE TABLE students (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL);
CREATE TABLE subjects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES students(id), name VARCHAR(100) NOT NULL, description VARCHAR(2000) NOT NULL);
CREATE TABLE tasks (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES students(id), subject_id BIGINT NOT NULL REFERENCES subjects(id), title VARCHAR(150) NOT NULL, description VARCHAR(4000) NOT NULL, due_date DATE NOT NULL, priority VARCHAR(10) NOT NULL CHECK(priority IN ('LOW','MEDIUM','HIGH')), status VARCHAR(15) NOT NULL CHECK(status IN ('TODO','IN_PROGRESS','DONE')), created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE auth_tokens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, owner_id BIGINT NOT NULL REFERENCES students(id), token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE INDEX subjects_owner ON subjects(owner_id);
CREATE INDEX tasks_owner_due ON tasks(owner_id, due_date);
CREATE INDEX tasks_subject ON tasks(subject_id);
